{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C63"],
      "claim": "Disopyramide, the closest structural analogue with a phenyl and 2-pyridyl on a central carbon and a basic amine side chain, has an absolute oral bioavailability of 78.23 ± 16.18% in normal volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Methadone, a lipophilic basic amine with two aryl groups, has an absolute oral bioavailability of 0.85 (95% CI 0.79-0.92) in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Encainide, a piperidine-containing drug, has an oral bioavailability of 32 ± 7% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Meperidine, a phenylpiperidine, has an absolute bioavailability of 0.63 in healthy volunteers, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Vismodegib, despite saturable absorption, has an absolute bioavailability of 31.8% in humans, above the threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is predicted to have high oral bioavailability (F >= 20%) based on strong experimental evidence from structurally similar basic amines, especially disopyramide (F ~78%) and methadone (F ~85%), and consistent F values above 20% across all relevant analogues.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "The impact of full ionization at pH 7.4 (pKa 10.35) on permeability and F is not directly measured.",
    "First-pass metabolism and transporter effects are unknown.",
    "The query's tertiary alcohol and pyridyl group may alter metabolism compared to disopyramide/methadone."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

